	// in single-line Temporal Markdown format.
	//
	// Optional: defaults to none/empty.
}

struct {
	TaskQueue string // TaskQueue - Name of the task queue that the activity needs to be scheduled on.
	//
	// Optional: The default task queue with the same name as the workflow task queue.
}

struct {
	VersioningIntent VersioningIntent // VersioningIntent - Specifies whether this activity should run on a worker with a compatible
	// build ID or not. See temporal.VersioningIntent.
	//
	// Deprecated: Use Worker Deployment Versioning instead. See https://docs.temporal.io/worker-versioning
}

struct {
	WaitForCancellation bool // WaitForCancellation - Whether to wait for canceled activity to be completed(
	// activity can be failed, completed, cancel accepted)
	//
	// Optional: default false
}

ActivityRequest struct {
	Name                string        `json:"name"`
	Input               []byte        `json:"input"`
	StartToCloseTimeout time.Duration `json:"start_to_close_timeout"`
}

ActivityResult[R any] struct {
	Result R
	Err    error
}

CallRequest struct {
	ID      uint64 `json:"id"`
	Op      uint32 `json:"op"`
	Payload []byte `json:"payload"`
}

struct {
	CronSchedule string // CronSchedule - Optional cron schedule for workflow. If a cron schedule is specified, the workflow will run
	// as a cron based on the schedule. The scheduling will be based on UTC time. Schedule for next run only happen
	// after the current run is completed/failed/timeout. If a RetryPolicy is also supplied, and the workflow failed
	// or timeout, the workflow will be retried based on the retry policy. While the workflow is retrying, it won't
	// schedule its next run. If next schedule is due while workflow is running (or retrying), then it will skip that
	// schedule. Cron workflow will not stop until it is terminated or canceled (by returning temporal.CanceledError).
	// The cron spec is as following:
	// ┌───────────── minute (0 - 59)
	// │ ┌───────────── hour (0 - 23)
	// │ │ ┌───────────── day of the month (1 - 31)
	// │ │ │ ┌───────────── month (1 - 12)
	// │ │ │ │ ┌───────────── day of the week (0 - 6) (Sunday to Saturday)
	// │ │ │ │ │
	// │ │ │ │ │
	// * * * * *
}

struct {
	Memo map // Memo - Optional non-indexed info that will be shown in list workflow.
	[string]any
}

struct {
	Namespace string // Namespace of the child workflow.
	//
	// Optional: the current workflow (parent)'s namespace will be used if this is not provided.
	//
	// Deprecated: Cross-namespace operations are disabled by default as of server 1.30.1.
}

struct {
	ParentClosePolicy go.temporal.io/api/enums/v1.ParentClosePolicy // ParentClosePolicy - Optional policy to decide what to do for the child.
	// Default is Terminate (if onboarded to this feature)
}

struct {
	FairnessKey string // FairnessKey is a short string that's used as a key for a fairness
	// balancing mechanism. It may correspond to a tenant id, or to a fixed
	// string like "high" or "low". The default is the empty string.
	//
	// The fairness mechanism attempts to dispatch tasks for a given key in
	// proportion to its weight. For example, using a thousand distinct tenant
	// ids, each with a weight of 1.0 (the default) will result in each tenant
	// getting a roughly equal share of task dispatch throughput.
	//
	// Fairness keys are limited to 64 bytes.
}

struct {
	FairnessWeight float32 // FairnessWeight for a task can come from multiple sources for
	// flexibility. From highest to lowest precedence:
	// 1. Weights for a small set of keys can be overridden in task queue
	//    configuration with an API.
	// 2. It can be attached to the workflow/activity in this field.
	// 3. The default weight of 1.0 will be used.
	//
	// Weight values are clamped to the range [0.001, 1000].
}

struct {
	PriorityKey int // PriorityKey is a positive integer from 1 to n, where smaller integers
	// correspond to higher priorities (tasks run sooner). In general, tasks in
	// a queue should be processed in close to priority order, although small
	// deviations are possible.
	//
	// The maximum priority value (minimum priority) is determined by server
	// configuration, and defaults to 5.
	//
	// The default value when unset or 0 is calculated by (min+max)/2. With the
	// default max of 5, and min of 1, that comes out to 3.
}

struct {
	Priority Priority // Priority - Optional priority settings that control relative ordering of
	// task processing when tasks are backed up in a queue.
	//
	// WARNING: Task queue priority is currently experimental.
}

struct {
	BackoffCoefficient float64 // Coefficient used to calculate the next retry backoff interval.
	// The next retry interval is previous interval multiplied by this coefficient.
	// Must be 1 or larger. Default is 2.0.
}

struct {
	InitialInterval time.Duration // Backoff interval for the first retry. If BackoffCoefficient is 1.0 then it is used for all retries.
	// If not set or set to 0, a default interval of 1s will be used.
}

struct {
	MaximumAttempts int32 // Maximum number of attempts. When exceeded the retries stop even if not expired yet.
	// If not set or set to 0, it means unlimited, and rely on activity ScheduleToCloseTimeout to stop.
}

struct {
	MaximumInterval time.Duration // Maximum backoff interval between retries. Exponential backoff leads to interval increase.
	// This value is the cap of the interval. Default is 100x of initial interval.
}

struct {
	NonRetryableErrorTypes [ // Non-Retriable errors. This is optional. Temporal server will stop retry if error type matches this list.
	//
	// Note:
	//  - cancellation is not a failure, so it won't be retried,
	//  - only StartToClose or Heartbeat timeouts are retryable.
	]string
}

struct {
	RetryPolicy *RetryPolicy // RetryPolicy specify how to retry child workflow if error happens.
	//
	// Optional: default is no retry
}

struct {
	SearchAttributes map // SearchAttributes - Optional indexed info that can be used in query of List/Scan/Count workflow APIs. The key and value type must be registered on Temporal server side.
	// Use GetSearchAttributes API to get valid key and corresponding value type.
	// For supported operations on different server versions see [Visibility].
	//
	// Deprecated: Use TypedSearchAttributes instead.
	//
	// [Visibility]: https://docs.temporal.io/visibility
	[string]any
}

struct {
	StaticDetails string // Details - General fixed details for this child workflow execution that will appear in UI/CLI. This can be in
	// Temporal markdown format and can span multiple lines. This is a fixed value on the workflow that cannot be
	// updated. For details that can be updated, use SetCurrentDetails within the workflow.
	//
	// Optional: defaults to none/empty.
}

struct {
	StaticSummary string // StaticSummary is a single-line fixed summary for this child workflow execution that will appear in UI/CLI. This can be
	// in single-line Temporal Markdown format.
	//
	// Optional: defaults to none/empty.
}

struct {
	TaskQueue string // TaskQueue that the child workflow needs to be scheduled on.
	//
	// Optional: the parent workflow task queue will be used if this is not provided.
}

struct {
	TypedSearchAttributes SearchAttributes // TypedSearchAttributes - Specifies Search Attributes that will be attached to the Workflow. Search Attributes are
	// additional indexed information attributed to workflow and used for search and visibility. The search attributes
	// can be used in query of List/Scan/Count workflow APIs. The key and its value type must be registered on Temporal
	// server side. For supported operations on different server versions see [Visibility].
	//
	// Optional: default to none.
	//
	// [Visibility]: https://docs.temporal.io/visibility
}

struct {
	VersioningIntent VersioningIntent // VersioningIntent specifies whether this child workflow should run on a worker with a
	// compatible build ID or not. See VersioningIntent.
	//
	// Deprecated: Build-id based versioning is deprecated in favor of worker deployment based versioning and will be removed soon.
	//
	// WARNING: Worker versioning is currently experimental
}

struct {
	WaitForCancellation bool // WaitForCancellation - Whether to wait for canceled child workflow to be ended (child workflow can be ended
	// as: completed/failed/timedout/terminated/canceled)
	//
	// Optional: default false
}

struct {
	WorkflowExecutionTimeout time.Duration // WorkflowExecutionTimeout - The end to end timeout for the child workflow execution including retries
	// and continue as new.
	//
	// Optional: defaults to unlimited.
}

struct {
	WorkflowID string // WorkflowID of the child workflow to be scheduled.
	//
	// Optional: an auto generated workflowID will be used if this is not provided.
}

struct {
	WorkflowIDReusePolicy go.temporal.io/api/enums/v1.WorkflowIdReusePolicy // WorkflowIDReusePolicy - Controls how the server handles attempts to reuse the ID of a completed workflow.
	// This can be useful for dedupe logic if set to WorkflowIdReusePolicyRejectDuplicate.
	//
	// Optional: defaults to AllowDuplicate.
}

struct {
	WorkflowRunTimeout time.Duration // WorkflowRunTimeout - The timeout for a single run of the child workflow execution. Each retry or
	// continue as new should obey this timeout. Use WorkflowExecutionTimeout to specify how long the parent
	// is willing to wait for the child completion.
	//
	// Optional: defaults to WorkflowExecutionTimeout
}

struct {
	WorkflowTaskTimeout time.Duration // WorkflowTaskTimeout - Maximum execution time of a single Workflow Task. In the majority of cases there is
	// no need to change this timeout. Note that this timeout is not related to the overall Workflow duration in
	// any way. It defines for how long the Workflow can get blocked in the case of a Workflow Worker crash.
	// Default is 10 seconds. Maximum value allowed by the Temporal Server is 1 minute.
}

ChildSignalRequest struct {
	Header                      map[string][]byte
	ID                          uint64
	Namespace, WorkflowID, Name string
	Payloads                    []byte
}

struct {
	Get func(ctx context.Context, valuePtr any) error
}

struct {
	SignalChildWorkflow func(ctx context.Context, signalName string, data any) Future
}

struct {
	ToChannel func() <- // ToChannel returns a new buffered channel carrying one result, then closes
	// it. Receiving or ignoring the channel does not cancel the operation.
	chan FutureResult
}

ChildWorkflowFuture interface {
	Future
	GetChildWorkflowExecution() Future
	SignalChildWorkflow(ctx context.Context, signalName string, data any) Future
}

